content.text:
{
  "name": "xArm机械臂",
  "name_en": "xArm robotic arm",
  "manufacturer": "UFACTORY",
  "description": "一款可编程多轴机械臂，可按G代码或预定义路径执行运动任务。在实验室中常用于自动化取放、样品转运、定位与重复轨迹操作等流程。",
  "description_en": "A programmable multi-axis robotic arm that can execute motion tasks from G-code or predefined paths. In laboratories, it is commonly used for automated pick-and-place, sample transfer, positioning, and repeatable motion workflows.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与机械臂的通信会话。",
      "description_en": "Close the communication session with the robotic arm."
    },
    {
      "action_name": "auto-execute",
      "description": "执行一条G代码命令。",
      "description_en": "Execute a single G-code command."
    },
    {
      "action_name": "auto-execute_file",
      "description": "执行G代码文件中的指令序列。",
      "description_en": "Execute the command sequence in a G-code file."
    }
  ],
  "tag_hints": [
    "robotic arm",
    "lab automation",
    "G-code motion control",
    "sample handling",
    "pick-and-place",
    "multi-axis positioning"
  ]
}

